(()=>{document.querySelectorAll("[data-explorer]").forEach(e=>{if(e.dataset.bound)return;e.dataset.bound="true";const n=e.querySelector("[data-explorer-load]"),t=e.querySelector("iframe"),s=e.querySelector('[role="status"]');n.addEventListener("click",()=>{if(t.hasAttribute("src"))return;n.hidden=!0,t.hidden=!1,s.hidden=!1,t.addEventListener("load",()=>{s.hidden=!0},{once:!0}),t.src=t.dataset.explorerSrc,t.focus({preventScroll:!0})})})})()